// Typed access to the canonical evaluation document.
//
// frontend/data/evals.json is the single source of truth for every number the
// product and the paper display. It is generated by `python3 ml/run_evals.py`,
// which folds the tabular suite (ml/artifacts/results.json) and the neural
// coder and data engine numbers (data/model_evals.json) into one file. Nothing
// in the UI should read those source files directly anymore; read this instead.

import doc from '@/data/evals.json'

export type MetricKind = 'measured' | 'deferred' | 'by_construction'
export type MetricUnit = 'fraction' | 'ratio' | 'ms' | 'count'

export interface EvalMetric {
  key: string
  label: string
  value: number | null
  unit: MetricUnit
  n: number | null
  dataset: string
  source: string
  kind: MetricKind
  higher_is_better: boolean
  threshold?: { min?: number; max?: number }
  caveat?: string
}

export interface EvalGroup {
  id: string
  title: string
  blurb: string
  metrics: EvalMetric[]
}

export interface EvalDataset {
  name: string
  provenance: string
  trust: 'low' | 'medium' | 'high'
  caveat: string
}

export interface EvalsDoc {
  schema_version: number
  generated: string
  commit: string | null
  sources: Record<string, string | null>
  datasets: Record<string, EvalDataset>
  groups: EvalGroup[]
}

export const evals = doc as unknown as EvalsDoc

/** Human readable value, or a placeholder when a metric is not yet measured. */
export function formatMetric(m: EvalMetric): string {
  if (m.value == null) return 'pending'
  switch (m.unit) {
    case 'fraction':
      return `${Math.round(m.value * 100)}%`
    case 'ratio':
      return m.value.toFixed(2)
    case 'ms':
      return `${Math.round(m.value)} ms`
    case 'count':
      return `${m.value}`
    default:
      return `${m.value}`
  }
}

export const KIND_LABEL: Record<MetricKind, string> = {
  measured: 'Measured',
  deferred: 'Deferred',
  by_construction: 'By construction',
}

/** Brand color per status, used for chips and accents. */
export const KIND_COLOR: Record<MetricKind, string> = {
  measured: '#34d399',
  deferred: '#fbbf24',
  by_construction: '#22d3ee',
}

export const TRUST_COLOR: Record<EvalDataset['trust'], string> = {
  high: '#34d399',
  medium: '#fbbf24',
  low: '#94a3b8',
}

export function metricsByKind(kind: MetricKind): EvalMetric[] {
  return evals.groups.flatMap((g) => g.metrics).filter((m) => m.kind === kind)
}

export function findMetric(key: string): EvalMetric | undefined {
  return evals.groups.flatMap((g) => g.metrics).find((m) => m.key === key)
}
